        if (mut & 8u) { if ((s16)DSW(rec + 0x36u) <= 0) return 0u; }    /* @r36: <= 0 */
        else if (mut & 64u) { if ((s32)DSD(rec + 0x36u) < 0) return 0u; }   /* @w36: a dword read */
        else if ((s16)DSW(rec + 0x36u) < 0) return 0u;
