    s32 n = (mut & 2u) ? (s32)(u32)(u16)r[R_EDX] : (s32)(s16)r[R_EDX];  /* @nzext */
    s32 nn = (mut & 4u) ? n : (s32)((u32)n * (u32)n);                   /* @sq */
