    if (mut & 0x20u) return (u32)q;                                     /* @noround */
    if (mut & 0x40u) return (u32)(q + 1);                               /* @always */
    if ((double)q + 0.5 < (double)(((mut & 0x80u) ? q : (s32)(s16)q) + 1))      /* @s16 */
        return (u32)q;
