    w = (s32)(s16)DSW(ctx[(mut & 0x20u) ? 5 : 4] + 0x34u);              /* @rec */
    if (gt) return (u32)((mut & 0x40u) ? (w > 0) : (w >= 0));           /* @ge */
    return (u32)((mut & 0x80u) ? (w < 0) : (w <= 0));                   /* @le */
