    if (!(mut & 8192u)) DSD(slot + 0x18u) = which ? 0u : 0x0003FD30u;                   /* @cb18 */
    if (!(mut & 16384u)) DSD(slot + 0x1Cu) = which ? 0u : 0x0003FDD8u;                  /* @cb1c */
