    u32 cur = DSD(DSD(slot) + ((mut & 128u) ? 4u : 8u));            /* @cur */
    if ((mut & 16u) ? (cur <= k_lo[ch]) : (cur < k_lo[ch])) return 0u;   /* @lo */
    if ((mut & 32u) ? (cur >= k_hi[ch]) : (cur > k_hi[ch])) return 0u;   /* @hi */
